#!/usr/bin/env node
/**
 * Builds the per-skill catalogue that GUIDE.md carries, from the skills themselves.
 *
 *   node scripts/skill-index.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..')

export const START = '<!-- antislop:skills:start -->'
export const END = '<!-- antislop:skills:end -->'

// One plain-English line per skill, and the order the guide lists them in. The frontmatter
// description is written for an agent to match on, not for a person to read.
const NOTES = {
  antislop:
    'The core, and it is always loaded. All 38 rules and the Delivery Gate live here, so every task gets them whether or not you pick anything else. The five skills below add depth to it.',
  'antislop-ui':
    'Load it when the AI builds or restyles anything you can see: color, layout, cards, buttons, motion.',
  'antislop-copywriting':
    'Load it when the AI writes or edits text: headlines, buttons, emails, or a page of prose. It removes the excited, empty voice and the made-up numbers.',
  'antislop-human':
    'Load it when real people have to use the result. Readable colors, keyboard use, visible focus, button states, and the contrast checker.',
  'antislop-layoutmobile':
    'Load it when the same page has to work on a phone and on a desktop. Reflow, breakpoints, overflow, tap targets, mobile navigation.',
  'antislop-code':
    'Load it when the AI writes or reviews code comments. It removes the ones an AI adds out of habit and keeps the ones that carry information.',
}

// A pattern entry opens with one of these labels; every other heading under a skill is prose.
const ENTRY = /^\s*-\s*\*\*(?:Tell|The pattern):\*\*/m
// A fenced example can hold a '### ' line of its own, so read with the fences taken out.
const unfenced = (text) => text.replace(/^[ \t]*(?:```|~~~)[\s\S]*?^[ \t]*(?:```|~~~)[ \t]*$/gm, '')

const blocksOf = (body, level) => body.split(new RegExp(`^${level} `, 'm')).slice(1)

const HEAD = '| What it covers | The patterns it names |\n|----------------|-----------------------|'

export function buildIndex() {
  const names = fs
    .readdirSync(path.join(root, 'skills'), { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)

  const unlisted = names.filter((n) => !NOTES[n])
  if (unlisted.length) throw new Error(`scripts/skill-index.mjs has no intro for: ${unlisted.join(', ')}`)
  const gone = Object.keys(NOTES).filter((n) => !names.includes(n))
  if (gone.length) throw new Error(`scripts/skill-index.mjs describes a skill that is gone: ${gone.join(', ')}`)

  const out = []
  for (const name of Object.keys(NOTES)) {
    const raw = fs.readFileSync(path.join(root, 'skills', name, 'SKILL.md'), 'utf8').replace(/\r\n/g, '\n')
    const rows = []
    for (const section of blocksOf(unfenced(raw), '##')) {
      const title = section.split('\n')[0].trim()
      const found = blocksOf(section, '###')
        .filter((block) => ENTRY.test(block))
        .map((block) => block.split('\n')[0].trim())
      if (found.length) rows.push(`| ${title} | ${found.join(', ')} |`)
    }
    out.push(`### ${name}`, '', NOTES[name], '')
    if (rows.length) out.push(HEAD, ...rows, '')
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n'
}

// Run directly to write it into the guide; imported by check-repo to prove the guide is current.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const file = path.join(root, 'GUIDE.md')
  const guide = fs.readFileSync(file, 'utf8')
  const from = guide.indexOf(START)
  const to = guide.indexOf(END)
  if (from === -1 || to === -1) throw new Error(`GUIDE.md has no ${START} ... ${END} pair`)
  const eol = guide.includes('\r\n') ? '\r\n' : '\n'
  const block = buildIndex().replace(/\n/g, eol)
  fs.writeFileSync(file, guide.slice(0, from + START.length) + eol + block + guide.slice(to))
  console.log('Regenerated the skill catalogue in GUIDE.md')
}

{
  "name": "anti-slop",
  "interface": {
    "displayName": "antislop"
  },
  "plugins": [
    {
      "name": "antislop",
      "source": {
        "source": "local",
        "path": "./"
      },
      "policy": {
        "installation": "AVAILABLE"
      },
      "category": "Productivity"
    }
  ]
}

#!/usr/bin/env node
import path from 'node:path'
import pc from 'picocolors'
import { intro, outro, select, multiselect, confirm, isCancel, cancel, log, spinner } from '@clack/prompts'
import { banner } from './lib/banner.mjs'
import { configureMode } from './lib/settings.mjs'
import {
  CORE,
  AGENTS,
  skillSourceDir,
  resolveTargets,
  detectAgents,
  detectConflicts,
  detectDuplicateReads,
  detectPluginDoors,
  installSkills,
  installedVersion,
  updateAll,
  updatePointers,
  VERSION,
} from './lib/install.mjs'

const EXTRA_SKILLS = [
  { value: 'antislop-ui', label: 'antislop-ui', hint: 'UI and visual design rules' },
  { value: 'antislop-copywriting', label: 'antislop-copywriting', hint: 'copywriting and text rules' },
  { value: 'antislop-human', label: 'antislop-human', hint: 'accessibility, with the contrast checker' },
  { value: 'antislop-layoutmobile', label: 'antislop-layoutmobile', hint: 'responsive layout rules' },
  { value: 'antislop-code', label: 'antislop-code', hint: 'code comment rules' },
]

function stop(message) {
  cancel(message)
  process.exit(0)
}

// Show the folder the chosen location actually writes. Agents with their own global
// folder (OpenCode, Antigravity) differ from the project one.
function displayDir(agent, location) {
  return location === 'global' ? `~/${agent.globalDir ?? agent.dir}` : agent.dir
}

// A plugin door keeps its own copy, so --update cannot reach it. Name the command for
// the ones found rather than send the reader back to a table in the guide.
function printPluginDoors(found) {
  if (found.length === 0) return
  console.log('\nInstalled as a plugin (these keep their own copy, so updating them is separate):')
  for (const p of found) {
    console.log(`  ${p.door.label}${p.version ? ` ${p.version}` : ''}`)
    console.log(`    ${p.door.update}`)
  }
}

async function main() {
  // A mistyped mode is a user error, so it gets one line like the terminal guard below
  // rather than the stack trace the top-level catch would print.
  if (process.argv[2] === '--mode') {
    try {
      console.log(configureMode(process.argv.slice(3)))
    } catch (error) {
      console.error(`antislop: ${error.message}`)
      process.exit(1)
    }
    return
  }
  if (process.argv.includes('--version') || process.argv.includes('-v')) {
    console.log(`antislop ${VERSION}`)
    return
  }

  // --update is the non-interactive path, so it runs before the terminal guard and prints
  // plain lines: an update is something a script or a user in a hurry can run unattended.
  if (process.argv.includes('--update')) {
    const { results, pointers } = updateAll()
    if (results.length === 0) {
      console.log(`antislop ${VERSION}: no installed folders found. Nothing to update.`)
    } else {
      for (const r of results) {
        const from = r.from ? `antislop ${r.from}` : 'an older release that records no version'
        console.log(`${r.path}`)
        console.log(`  ${from} -> antislop ${VERSION}  (${r.skills.length} skill(s) for ${r.agents.join(', ')})`)
      }
      console.log(`\nUpdated ${results.length} folder(s) to antislop ${VERSION}.`)
      if (pointers.length > 0) {
        console.log(`Pointer refreshed in ${pointers.map((p) => path.basename(p)).join(', ')}.`)
      }
      console.log('Start a new agent session for the new rules to load.')
    }
    printPluginDoors(detectPluginDoors())
    return
  }

  // Without a terminal the prompts read EOF at once: the run printed the banner, installed
  // nothing, and still exited 0, so a script around it saw success. Fail loudly instead.
  if (!process.stdin.isTTY) {
    console.error('antislop: this installer needs a terminal. Run `npx antislop-ai` in an interactive shell.')
    process.exit(1)
  }

  console.log(banner())
  intro('Install antislop into your agent setup')

  if (!skillSourceDir()) {
    stop('Could not find the antislop skills. Reinstall the antislop package.')
  }

  log.step('Choose your skills')
  console.log(`  ${pc.green('●')} ${pc.bold(CORE)}  ${pc.dim('core rules, always on')}`)

  const extra = await multiselect({
    message: 'Extra skills to install',
    options: EXTRA_SKILLS,
    required: false,
  })
  if (isCancel(extra)) stop('Install cancelled.')
  const skills = [CORE, ...(extra ?? [])]

  log.step('Choose where antislop goes')
  const location = await select({
    message: 'Install location',
    options: [
      { value: 'project', label: 'This project', hint: 'only this folder' },
      { value: 'global', label: 'Everywhere', hint: 'all your projects' },
    ],
  })
  if (isCancel(location)) stop('Install cancelled.')

  log.step('Choose which agents get antislop')
  const detected = detectAgents(location)
  const chosen = await multiselect({
    message: 'Which agent(s) should antislop install into?',
    options: AGENTS.map((a) => ({
      value: a.id,
      label: a.label,
      hint: detected.includes(a.id) ? `found here (${displayDir(a, location)})` : `will create ${displayDir(a, location)}`,
    })),
    required: 'Pick at least one agent.',
    initialValues: detected,
  })
  if (isCancel(chosen)) stop('Install cancelled.')

  const targets = resolveTargets(location, chosen)
  await log.message(
    'Installing into:\n' + targets.map((t) => '  ' + t.path).join('\n'),
    { symbol: pc.cyan('│') }
  )

  const conflicts = detectConflicts({ skills, targets })
  let overwrite = false
  if (conflicts.length > 0) {
    // Overwriting is how an update happens, and the version on disk is the one fact
    // the user cannot look up anywhere. Name both sides so the choice is obvious.
    const found = [...new Set(targets.map((t) => installedVersion(t.path)).filter(Boolean))]
    const have = found.length > 0 ? `antislop ${found.join(' and ')}` : 'an antislop old enough that it records no version'
    log.warn(`Already here: ${have}. This installer carries ${VERSION}.`)

    const answer = await select({
      message: `${conflicts.length} skill folder(s) already exist. What should I do?`,
      options: [
        { value: 'overwrite', label: 'Overwrite them', hint: `update to ${VERSION}` },
        { value: 'keep', label: 'Keep what is there', hint: 'stay on what is installed' },
      ],
    })
    if (isCancel(answer)) stop('Install cancelled.')
    overwrite = answer === 'overwrite'
  }

  const proceed = await confirm({
    message: `Install ${skills.length} skill(s) now?`,
    initialValue: true,
  })
  if (isCancel(proceed) || proceed === false) stop('Install cancelled.')

  const spin = spinner()
  spin.start('Installing skills...')
  const written = installSkills({ skills, targets, overwrite })
  const pointers = location === 'project' ? updatePointers({ targets, skills }) : []
  spin.stop('Done.')

  if (pointers.length > 0) {
    log.step('Pointer written to ' + pointers.map((p) => path.basename(p)).join(', '))
  }

  const folderCount = new Set(written.map((w) => path.dirname(w.path))).size
  if (written.length > 0) {
    outro(`Installed ${written.length} skill(s) into ${folderCount} agent folder(s).`)
    console.log(pc.dim('antislop is ready. The next agent session loads it.'))
  } else {
    // "Existing folders were kept" used to read as success. The copies are the
    // old release, so say that plainly and name the choice that fixes it.
    outro('Nothing new to install. Existing folders were kept.')
    console.log(pc.dim('They may be older than this release. To update, run it again and pick "Overwrite them".'))
  }

  // Hermes gates project skills behind a one-time, per-repo trust step, so name it here
  // rather than let the user meet it as a banner after the install looked finished.
  if (location === 'project' && targets.some((t) => t.agents.some((a) => a.id === 'hermes'))) {
    log.warn('Hermes needs one more step: run `hermes skills trust` in this project.')
  }

  // Pi gates its project folders too, but has no command for it: it asks on the first
  // run and `/trust` saves the answer, so a command here would be the wrong instruction.
  if (location === 'project' && targets.some((t) => t.agents.some((a) => a.id === 'pi'))) {
    log.warn('Pi will ask you to trust this project before it loads the skills. `/trust` saves that answer.')
  }

  // Two folders holding the same skill names is how a skill goes missing in OpenCode,
  // which reads both and does not document which copy it keeps.
  for (const dup of detectDuplicateReads({ targets, location })) {
    log.warn(
      `${dup.agent.label} reads both ${dup.paths.join(' and ')}, and antislop is now in both. ` +
        'It may load either copy. Remove one of them to be safe.'
    )
  }

  // Installing through the installer does not update a plugin door the user also has,
  // and nothing else would tell them that copy exists.
  printPluginDoors(detectPluginDoors())
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})

#!/usr/bin/env node
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { spawnSync } from 'node:child_process'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const worker = path.join(__dirname, 'smoke-worker.mjs')

function tree(dir, prefix = '') {
  const out = []
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      out.push(prefix + entry.name + '/')
      out.push(...tree(p, prefix + '  '))
    } else {
      out.push(prefix + entry.name)
    }
  }
  return out
}

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'antislop-smoke-'))
const result = spawnSync(process.execPath, [worker], { cwd: tmp, encoding: 'utf8' })
console.log('--- worker output ---')
console.log(result.stdout.trim())
if (result.status !== 0) console.error('worker stderr:', result.stderr)

console.log('\n--- files written to temp project ---')
console.log(tree(tmp).join('\n'))

for (const name of ['CLAUDE.md', 'AGENTS.md', 'GEMINI.md']) {
  const entry = path.join(tmp, name)
  if (!fs.existsSync(entry)) continue
  console.log(`\n--- ${name} ---`)
  console.log(fs.readFileSync(entry, 'utf8'))
}

const coreSkill = path.join(tmp, '.claude', 'skills', 'antislop', 'SKILL.md')
const coreInstalled = fs.existsSync(coreSkill)
console.log('\ncore SKILL.md exists:', coreInstalled)

// Every failure is collected here and decided before cleanup, so a failing run
// still leaves a tidy temp dir behind.
const reasons = []
if (result.status !== 0) reasons.push(`worker exited ${result.status}`)
if (!coreInstalled) reasons.push('core SKILL.md was not installed')

// The wizard needs a terminal. With stdin closed it used to print its prompts, install
// nothing, and still exit 0, so callers saw success. It has to refuse and say why.
// Loading it needs the cli's dependencies, so a bare checkout reports a skip instead.
const cliDeps = fs.existsSync(path.join(__dirname, '..', 'node_modules', '@clack'))
if (cliDeps) {
  const invalidMode = spawnSync(process.execPath, [path.join(__dirname, '..', 'index.mjs'), '--mode', 'invalid'], {
    cwd: tmp,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  const cleanError = /^antislop: /.test(invalidMode.stderr) && !/\n\s+at /.test(invalidMode.stderr)
  if (invalidMode.status !== 1 || !/Usage: antislop-ai --mode/.test(invalidMode.stderr) || !cleanError) {
    reasons.push('the mode command must exit 1 on one clean line, not a stack trace')
  }
  const noTty = spawnSync(process.execPath, [path.join(__dirname, '..', 'index.mjs')], {
    cwd: tmp,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  const refused = noTty.status === 1 && /needs a terminal/.test(noTty.stderr)
  console.log('no-terminal run: exit', noTty.status, '| refused:', refused)
  if (!refused) reasons.push(`a no-terminal run should exit 1 and say why, got exit ${noTty.status}`)
} else {
  console.log('no-terminal run: skipped, cli dependencies are not installed')
}

fs.rmSync(tmp, { recursive: true, force: true })
console.log('\ncleaned up temp project.')

if (reasons.length > 0) {
  console.error('\nsmoke test failed: ' + reasons.join('; '))
  process.exit(1)
}
console.log('smoke test passed.')

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import assert from 'node:assert/strict'
import { configureMode, readSettings, resolveSettingsPath } from '../lib/settings.mjs'
import {
  AGENTS,
  CORE,
  PLUGIN_DOORS,
  skillSourceDir,
  resolveTargets,
  detectAgents,
  detectConflicts,
  detectDuplicateReads,
  installSkills,
  installedVersion,
  updateAll,
  updatePointers,
  VERSION,
} from '../lib/install.mjs'

const skills = ['antislop', 'antislop-ui']

assert.equal(
  resolveSettingsPath({ platform: 'linux', env: {}, home: '/home/ada' }),
  '/home/ada/.config/antislop/settings.json'
)
assert.equal(
  resolveSettingsPath({ platform: 'darwin', env: {}, home: '/Users/ada' }),
  '/Users/ada/.config/antislop/settings.json'
)
assert.equal(
  resolveSettingsPath({ platform: 'win32', env: { APPDATA: 'C:\\Users\\Ada\\AppData\\Roaming' }, home: 'C:\\Users\\Ada' }),
  'C:\\Users\\Ada\\AppData\\Roaming\\antislop\\settings.json'
)
assert.equal(
  resolveSettingsPath({ platform: 'win32', env: {}, home: 'C:\\Users\\Ada' }),
  'C:\\Users\\Ada\\.config\\antislop\\settings.json'
)

const settingsFile = path.join(process.cwd(), 'preferences', 'settings.json')
assert.match(configureMode([], settingsFile), /ask \(default\)/)
assert.equal(fs.existsSync(settingsFile), false)
for (const mode of ['during', 'after', 'ask']) {
  assert.match(configureMode([mode], settingsFile), new RegExp(`global mode: ${mode}`))
  assert.equal(readSettings(settingsFile).mode, mode)
  assert.match(configureMode([], settingsFile), new RegExp(`global mode: ${mode}`))
}
fs.writeFileSync(settingsFile, '{"other":true,"mode":"during"}')
configureMode(['after'], settingsFile)
assert.deepEqual(readSettings(settingsFile), { other: true, mode: 'after' })
assert.throws(() => configureMode(['invalid'], settingsFile), /Usage:/)
assert.throws(() => configureMode(['during', 'extra'], settingsFile), /Usage:/)
assert.equal(readSettings(settingsFile).mode, 'after')
for (const content of ['{broken', 'null', '[]', '"during"']) {
  fs.writeFileSync(settingsFile, content)
  // The refusal is right, but it has to name the way out: --mode is the only command
  // that can fix this file, so a message with no instruction is a dead end.
  assert.throws(() => configureMode(['during'], settingsFile), /Fix or delete/)
  assert.equal(fs.readFileSync(settingsFile, 'utf8'), content)
}
for (const mode of ['invalid', null, 1]) {
  fs.writeFileSync(settingsFile, JSON.stringify({ mode }))
  assert.throws(() => configureMode([], settingsFile), /Invalid mode/)
  configureMode(['during'], settingsFile)
  assert.equal(readSettings(settingsFile).mode, 'during')
}
console.log('ok   global mode preferences: persistence, validation, and preservation')

const failures = []

/** Prints the line this always printed and records whether it held, so one run
 * reports every break rather than stopping at the first.
 */
const check = (label, actual, expected) => {
  const ok = JSON.stringify(actual) === JSON.stringify(expected)
  console.log(ok ? `ok   ${label}:` : `FAIL ${label}:`, actual, ok ? '' : `(expected ${JSON.stringify(expected)})`)
  if (!ok) failures.push(label)
}

// Fresh state: nothing detected, and the default selection is every agent.
const fresh = detectAgents('project')
check('A detected (fresh project)', fresh, [])
const defaultTargets = resolveTargets('project')
console.log('A default targets:', defaultTargets.map((t) => `${t.agents.map((a) => a.id).join('+')}@${t.path} exists=${t.exists}`).join(' | '))
// Copilot, Kimi Code, and Amp share Antigravity's folder, so twelve resolve to nine.
check('A twelve agents over nine folders', [AGENTS.length, defaultTargets.length], [12, 9])
check('A copilot and kimi share the antigravity folder', resolveTargets('project', ['antigravity', 'copilot', 'kimi']).length, 1)

// Claude Code only, via explicit selection (old behavior preserved).
const targets = resolveTargets('project', ['claude'])
let written = installSkills({ skills, targets, overwrite: false })
let pointers = updatePointers({ targets, skills })
console.log('B targets:', targets.map((t) => `${t.agents.map((a) => a.id).join('+')}@${t.path} exists=${t.exists}`).join(' | '))
console.log('B written:', written.map((w) => `${w.agents.join('+')}:${w.skill}`).join(', '))
check('B pointers', pointers.map((p) => path.basename(p)), ['CLAUDE.md'])
const pointer = fs.readFileSync(pointers[0], 'utf8')
assert.match(pointer, /explicit session instruction first, then global preference, then ask/)
assert.match(pointer, /A session instruction always wins/)
assert.ok(pointer.includes('antislop active: <mode> (session override).'))
assert.ok(pointer.includes('antislop active: <mode> (global preference).'))
assert.ok(pointer.includes('ask during/after and end the response'))
assert.ok(pointer.includes('only at the start of the final answer, never in progress messages'))
assert.ok(pointer.includes('announce before the first edit and omit it from the final answer'))
assert.ok(pointer.includes('`.claude/skills/antislop/SKILL.md`'))
assert.ok(pointer.includes('`.claude/skills/antislop-ui/SKILL.md`'))

const conflicts = detectConflicts({ skills, targets })
written = installSkills({ skills, targets, overwrite: false })
check('C conflicts', conflicts.length, 2)
check('C written without overwrite', written.length, 0)
written = installSkills({ skills, targets, overwrite: true })
check('C overwritten', written.length, 2)

// Antigravity on a fresh project: .agents/ does not exist yet, install creates it.
const agTargets = resolveTargets('project', ['antigravity'])
console.log('D antigravity targets:', agTargets.map((t) => `${t.agents.map((a) => a.id).join('+')}@${t.path} exists=${t.exists}`).join(' | '), '(exists=false before install)')
const agWritten = installSkills({ skills, targets: agTargets, overwrite: false })
check('D antigravity written', agWritten.length, 2)
const agPointers = updatePointers({ targets: agTargets, skills })
check('D antigravity pointers', agPointers.map((p) => path.basename(p)), ['AGENTS.md'])
check('D .agents/skills/antislop/SKILL.md exists', fs.existsSync(path.join(process.cwd(), '.agents', 'skills', 'antislop', 'SKILL.md')), true)

// OpenCode, Cursor, and Gemini each install and point to their own entry file.
for (const agent of ['opencode', 'cursor', 'gemini']) {
  const t = resolveTargets('project', [agent])
  const w = installSkills({ skills, targets: t, overwrite: false })
  const pointers = updatePointers({ targets: t, skills })
  check(`D2 ${agent} written`, w.length, 2)
  check(`D2 ${agent} pointer`, pointers.map((p) => path.basename(p)), [agent === 'gemini' ? 'GEMINI.md' : 'AGENTS.md'])
  check(`D2 ${agent} folder exists`, fs.existsSync(path.join(process.cwd(), agent === 'gemini' ? '.gemini' : agent === 'cursor' ? '.cursor' : '.opencode', 'skills', 'antislop', 'SKILL.md')), true)
}

// Cline keeps a folder of its own and reads .claude/skills beside it, so both fill up.
const clineProject = resolveTargets('project', ['cline'])
check('D8 cline project target', clineProject[0].path, path.join(process.cwd(), '.cline', 'skills'))
check('D8 cline global target', resolveTargets('global', ['cline'])[0].path, path.join(os.homedir(), '.cline', 'skills'))
check('D8 cline written', installSkills({ skills, targets: clineProject, overwrite: false }).length, 2)
check('D8 cline pointer', updatePointers({ targets: clineProject, skills }).map((p) => path.basename(p)), ['AGENTS.md'])
check('D8 cline folder exists', fs.existsSync(path.join(process.cwd(), '.cline', 'skills', 'antislop', 'SKILL.md')), true)

// Amp shares the project's .agents/skills, which the Antigravity block already filled,
// but its global folder is a different path.
const ampProject = resolveTargets('project', ['amp'])
